def read_json(json_data):
    try:
        data = json.loads(json_data)
        consoleObj.log(f"JSON Data: {data}")
        for app in data:
            consoleObj.log(f"App: {app}")

    except json.JSONDecodeError as e:
        consoleObj.log(f"Failed to decode JSON: {e}")

def install_app(app_name, ipk_path, subscribe=True):
    sub = "true" if subscribe else "false"
    args = f"'{{\"id\":\"{app_name}\",\"ipkUrl\":\"{ipk_path}\", \"subscribe\":{sub}}}'"
    command = f"{install_appSrv} {args}"

    # Check if luna-send is available
    # if not shutil.which("luna-send"):
    #     consoleObj.log("luna-send command not found in PATH")
    #     return

    output = commandline.install_command(command, app_name)
    consoleObj.log(f"Output: {output}")


